#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_trie_insert_allocation_failure(void) {
    // Setup: create a valid trie root
    struct trie *root = NULL;
    int ret = trie_new(&root);
    TEST_ASSERT_EQUAL_INT(0, ret);
    TEST_ASSERT_NOT_NULL(root);

    // We need to trigger the path where:
    // 1. word_len != 0 (so we don't take the early return)
    // 2. index is within ALPHABET_SIZE (so we don't fail on invalid char)
    // 3. The child at index is NULL (so we try to allocate)
    // 4. The allocation inside trie_new fails (so ret == -1)
    // This matches the path: START -> ret=0 -> word_len !=0 -> index valid -> child NULL -> trie_new fails -> return -1

    // Use a valid lowercase letter 'a' (index 0)
    char *word = "a";
    unsigned int word_len = 1;

    // The setup (trie_new for root) used 1 allocation.
    // The next allocation will be the calloc inside trie_new for the child node.
    // We want that allocation to fail.
    malloc_fail_after(1); // First allocation (root) succeeded, fail the second (child)

    // Test: insert should fail due to allocation failure
    ret = trie_insert(root, word, word_len);
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Cleanup: root is still valid, free it
    trie_free(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_trie_insert_allocation_failure);
    return UNITY_END();
}

